import{_ as a,o as l,c as o,a4 as i}from"./chunks/framework.BDwB2oh8.js";const g=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"question/index.md","filePath":"question/index.md"}'),r={name:"question/index.md"};function t(n,e,s,d,c,p){return l(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h1><h2 id="落雪token在哪获取" tabindex="-1">落雪Token在哪获取 <a class="header-anchor" href="#落雪token在哪获取" aria-label="Permalink to “落雪Token在哪获取”">​</a></h2><p>点击这个链接 <a href="https://maimai.lxns.net/user/profile?tab=thirdparty" target="_blank" rel="noreferrer">https://maimai.lxns.net/user/profile?tab=thirdparty</a><br> 划到最下面，有一个叫<em><strong>个人 API 密钥</strong></em>的东西就是落雪Token了</p><h2 id="苹果自签教程" tabindex="-1">苹果自签教程 <a class="header-anchor" href="#苹果自签教程" aria-label="Permalink to “苹果自签教程”">​</a></h2><h3 id="一、准备工作" tabindex="-1">一、准备工作 <a class="header-anchor" href="#一、准备工作" aria-label="Permalink to “一、准备工作”">​</a></h3><p>在开始之前，请确认你手上有这些东西：</p><ul><li>一台电脑（Windows 7及以上或 macOS 10.12及以上）</li><li>一台iPhone/iPad（iOS 7及以上均可）</li><li>一根能用的数据线（能给你的设备充上电就行，当然原装的最好）</li><li>一个Apple ID（普通免费账号即可）</li><li>你要安装的IPA文件（请从可信来源获取）</li></ul><h3 id="二、下载并安装必要软件" tabindex="-1">二、下载并安装必要软件 <a class="header-anchor" href="#二、下载并安装必要软件" aria-label="Permalink to “二、下载并安装必要软件”">​</a></h3><h4 id="_0-怎么看自己电脑是多少位的-windows" tabindex="-1">0. 怎么看自己电脑是多少位的（Windows） <a class="header-anchor" href="#_0-怎么看自己电脑是多少位的-windows" aria-label="Permalink to “0. 怎么看自己电脑是多少位的（Windows）”">​</a></h4><ol><li>键盘按下 <code>Win + Pause/Break</code> 快捷键，直接打开系统信息页面。</li><li>或者右键点击【此电脑】→【属性】。</li><li>在弹出的系统窗口中，找到 <strong>系统类型</strong>，即可看到：<code>64位操作系统</code> / <code>32位操作系统</code>。</li></ol><blockquote><p>提示：现在绝大多数新电脑都是64位系统。</p></blockquote><h4 id="_1-下载并安装itunes-windows用户必做" tabindex="-1">1. 下载并安装iTunes（Windows用户必做） <a class="header-anchor" href="#_1-下载并安装itunes-windows用户必做" aria-label="Permalink to “1. 下载并安装iTunes（Windows用户必做）”">​</a></h4><p>⚠️ 重要提示：Windows用户必须安装苹果官网下载的iTunes版本，不能用Microsoft Store里面下载的版本。如果你已经安装了Microsoft Store版，请先卸载，再按下面的步骤安装官网版。</p><p>下载地址：</p><ul><li>64位Windows：<a href="https://www.apple.com/itunes/download/win64" target="_blank" rel="noreferrer">https://www.apple.com/itunes/download/win64</a></li><li>32位Windows：<a href="https://www.apple.com/itunes/download/win32" target="_blank" rel="noreferrer">https://www.apple.com/itunes/download/win32</a></li></ul><p>下载完成后双击安装包，一路点击&quot;下一步&quot;完成安装即可。</p><p>Mac用户：macOS系统已自带相关组件，不需要额外安装iTunes。</p><h4 id="_2-下载并安装sideloadly" tabindex="-1">2. 下载并安装Sideloadly <a class="header-anchor" href="#_2-下载并安装sideloadly" aria-label="Permalink to “2. 下载并安装Sideloadly”">​</a></h4><p>官方下载地址：<a href="https://sideloadly.io/" target="_blank" rel="noreferrer">https://sideloadly.io/</a></p><p>根据你的操作系统选择对应的版本：</p><ul><li>Windows 64位：<a href="https://sideloadly.io/SideloadlySetup64.exe" target="_blank" rel="noreferrer">https://sideloadly.io/SideloadlySetup64.exe</a></li><li>Windows 32位：<a href="https://sideloadly.io/SideloadlySetup32.exe" target="_blank" rel="noreferrer">https://sideloadly.io/SideloadlySetup32.exe</a></li><li>macOS：<a href="https://sideloadly.io/SideloadlySetup.dmg" target="_blank" rel="noreferrer">https://sideloadly.io/SideloadlySetup.dmg</a></li></ul><p>下载完成后：</p><ul><li>Windows：双击安装包，按提示完成安装</li><li>macOS：打开.dmg文件，将Sideloadly拖入Applications文件夹</li></ul><p>安装完成后，在桌面或应用程序中找到Sideloadly的图标，右键选择<strong>以管理员身份运行</strong>（Windows）或直接双击打开（macOS）。首次打开时软件可能会提示下载Anisette组件，点击<code>Yes</code>确认即可。</p><h3 id="三、连接手机与电脑" tabindex="-1">三、连接手机与电脑 <a class="header-anchor" href="#三、连接手机与电脑" aria-label="Permalink to “三、连接手机与电脑”">​</a></h3><ol><li>用数据线将iPhone/iPad连接到电脑的USB接口</li><li>首次连接时，手机上会弹出&quot;要信任此电脑吗？&quot;的提示，点击<strong>信任</strong></li><li>如果手机有锁屏密码，输入密码确认</li><li>打开Sideloadly，在软件界面的<code>iDevice</code>区域应该能看到你的设备名称和型号信息——这说明连接成功了</li></ol><blockquote><p>如果没显示设备：检查数据线是否插好，或者重新拔插一下。也可以先打开iTunes看看能不能识别到你的手机。</p></blockquote><h3 id="四、导入ipa文件" tabindex="-1">四、导入IPA文件 <a class="header-anchor" href="#四、导入ipa文件" aria-label="Permalink to “四、导入IPA文件”">​</a></h3><p>在Sideloadly软件界面中：</p><ul><li>直接将你的IPA文件拖拽到软件左上角的方框（或带文档图标的区域）里</li><li>或者点击该区域的图标，在弹窗中选择你的IPA文件</li></ul><p>拖入成功后，方框底部会显示该应用的名称。</p><h3 id="五、输入apple-id" tabindex="-1">五、输入Apple ID <a class="header-anchor" href="#五、输入apple-id" aria-label="Permalink to “五、输入Apple ID”">​</a></h3><ol><li>在Sideloadly界面中找到<code>Apple Account</code>或<code>Apple ID</code>输入框</li><li>输入你的Apple ID账号（邮箱地址）</li><li>点击下方的<code>Start</code>按钮</li><li>软件会弹窗要求输入Apple ID密码，输入后点击<code>OK</code></li></ol><blockquote><p>关于双重认证：如果你的Apple ID开启了双重认证，输入密码后手机可能会收到验证码，将验证码输入到Sideloadly的提示框中即可。</p><p>建议：可以专门注册一个新的Apple ID用来做签名，避免主账号的安全风险。</p></blockquote><h3 id="六、等待安装完成" tabindex="-1">六、等待安装完成 <a class="header-anchor" href="#六、等待安装完成" aria-label="Permalink to “六、等待安装完成”">​</a></h3><p>点击<code>Start</code>后，Sideloadly会开始为IPA签名并安装到你的手机上。这个过程可能需要几十秒到几分钟，请耐心等待。</p><p>软件界面下方的日志区域会显示安装进度。看到类似<code>Installation Complete</code>或<code>Done</code>的提示时，说明安装成功了。</p><h3 id="七、在手机上信任该应用-关键步骤" tabindex="-1">七、在手机上信任该应用（关键步骤！） <a class="header-anchor" href="#七、在手机上信任该应用-关键步骤" aria-label="Permalink to “七、在手机上信任该应用（关键步骤！）”">​</a></h3><p>安装完成后，不要直接点开应用——此时打开会提示&quot;未受信任的开发者&quot;。你需要先在手机设置中信任它。</p><p>操作步骤：</p><ol><li>打开iPhone的<strong>设置</strong>App</li><li>往下滑，找到<strong>通用</strong>并点击进入</li><li>再往下滑，找到<strong>VPN与设备管理</strong>并点击进入</li></ol><blockquote><p>注意：如果你的手机系统是iOS 15或更早的版本，这个选项叫<strong>描述文件与设备管理</strong></p></blockquote><ol start="4"><li>在<strong>开发者App</strong>区域，找到你刚才输入的那个Apple ID邮箱</li><li>点击进入，然后点击<strong>信任</strong>按钮</li><li>在弹出的确认框中再次点击<strong>信任</strong></li></ol><p>完成以上操作后，回到手机桌面，就可以正常打开并使用刚才安装的应用了。</p><h2 id="阿里云accesskeyid与accesskeysecret获取" tabindex="-1">阿里云accessKeyId与accessKeySecret获取 <a class="header-anchor" href="#阿里云accesskeyid与accesskeysecret获取" aria-label="Permalink to “阿里云accessKeyId与accessKeySecret获取”">​</a></h2><h3 id="一、前往阿里云机器翻译控制台开通机器翻译" tabindex="-1">一、前往阿里云机器翻译控制台开通机器翻译 <a class="header-anchor" href="#一、前往阿里云机器翻译控制台开通机器翻译" aria-label="Permalink to “一、前往阿里云机器翻译控制台开通机器翻译”">​</a></h3><p>点击直达 <a href="https://mt.console.aliyun.com/basic" target="_blank" rel="noreferrer">https://mt.console.aliyun.com/basic</a></p><h3 id="二、创建阿里云ram账号" tabindex="-1">二、创建阿里云RAM账号 <a class="header-anchor" href="#二、创建阿里云ram账号" aria-label="Permalink to “二、创建阿里云RAM账号”">​</a></h3><p>点击直达 <a href="https://ram.console.aliyun.com/overview?activeTab=workflow" target="_blank" rel="noreferrer">https://ram.console.aliyun.com/overview?activeTab=workflow</a></p><ol><li>在<strong>创建程序用户AccessKey</strong>里选择<em><strong>用于程序访问的超级用户</strong></em></li><li><strong>登录名称</strong>随便输入一个，划到最下面，点击<strong>执行配置</strong></li><li>接着点击<strong>身份管理</strong>里的<strong><a href="https://ram.console.aliyun.com/users" target="_blank" rel="noreferrer">用户</a></strong></li><li>点击<strong>新增授权</strong>，搜索<em><strong>机器翻译</strong></em>，勾选<strong>AliyunMTFullAccess</strong>，点击下面<strong>确认新增授权</strong></li><li>请务必牢记你的<strong>AccessKey ID</strong>和<strong>Access Key Secret</strong>，该页面关闭后将无法再次查看。</li></ol><h3 id="三、在软件里设置" tabindex="-1">三、在软件里设置 <a class="header-anchor" href="#三、在软件里设置" aria-label="Permalink to “三、在软件里设置”">​</a></h3><p>回到软件里，设置 - 翻译设置 - 输入，保存</p><h2 id="软件初次启动下载很久" tabindex="-1">软件初次启动下载很久 <a class="header-anchor" href="#软件初次启动下载很久" aria-label="Permalink to “软件初次启动下载很久”">​</a></h2><p>在v0.20.0到0.21.0之间，或者v0.19.0也可能有，因为石山代码没测试初次启动，软件已经报错了，但又由于flutter的特性不会崩掉<br> 还有一种原因是最新最热歌曲下载太慢，新版本已经移除在第一次启动时下载最新最热歌曲</p><h3 id="解决方法" tabindex="-1">解决方法 <a class="header-anchor" href="#解决方法" aria-label="Permalink to “解决方法”">​</a></h3><p>直接按返回键关闭更新窗口，然后切换到<strong>关于界面</strong>，点击<strong>更新数据</strong>，<strong>更新基础数据</strong></p>',56)])])}const b=a(r,[["render",t]]);export{g as __pageData,b as default};
